import { AfterViewInit, booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, inject, input, signal, ViewChild } from '@angular/core';
import { ButtonComponent } from 'espd-common/button';
import { PlaceholderService } from 'espd-common/placeholder';
import { BsDropdownDirective, BsDropdownModule } from 'ngx-bootstrap/dropdown';
import { DropdownDirective } from '../dropdown.directive';

type ButtonColor = 'primary' | 'success' | 'warning' | 'danger' | 'info' | 'dark' | 'link';

@Component({
	selector: 'espd-dropdown',
	templateUrl: './dropdown.component.html',
	styleUrls: ['./dropdown.component.scss'],
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [
		BsDropdownModule,
		ButtonComponent,
		DropdownDirective
	]
})
export class DropdownComponent implements AfterViewInit {
	private static nextId: number = 0;
	public color = input<ButtonColor>('primary');
	public secondary = input(false, { transform: booleanAttribute });
	public small = input(false, { transform: booleanAttribute });
	public rounded = input(false, { transform: booleanAttribute });
	public placement = input<'left' | 'right'>('left');
	public showChevron = input(true);
	public disabled = input(false, { transform: booleanAttribute });
	public id = signal<number>(DropdownComponent.nextId++);

	@ViewChild(DropdownDirective)
	private dropdownDirective!: DropdownDirective;

	@ViewChild(BsDropdownDirective)
	private bsDropdownDirective!: BsDropdownDirective;

	@ViewChild(ButtonComponent, { read: ElementRef })
	private dropdownButton!: ElementRef;

	private cdr = inject(ChangeDetectorRef);
	private placeholderService = inject(PlaceholderService);

	public onChildClick(): void {
		this.placeholderService.saveFocusLocation(this.dropdownButton.nativeElement, this.dropdownDirective);
	}

	ngAfterViewInit() {
		// ChangeDetectionStrategy.OnPush does not pick up the changes to remove the show classes. Force change detection
		this.bsDropdownDirective.onHidden.subscribe(() => this.cdr.detectChanges());
	}
}